-- Oon Jai online-menu reference import, v120. Run in Supabase SQL Editor after v119.
-- Inserts missing names only; never edits existing menu, ingredient, or category records.
-- Source has no serving quantities, purchase costs, or inventory mappings. Imported menu
-- entries can be saved as unpaid orders; POS payment stays blocked until reviewed.
-- Install this function, then use Menu > Import online menu while signed in as an administrator.
create or replace function public.pos_import_online_menu120() returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $import$
